parameters.jsCode:
// One request = one item in, exactly one item out.
// Output: { valid:true, customer_code, description, priority, request_id }
//     or: { valid:false, status, error, message }
const req = $input.first().json;

const fail = (status, error, message) =>
  [{ json: { valid: false, status, error, message } }];

// --- 1. Authentication -------------------------------------------------
const expected = $env.WEBHOOK_API_KEY;
if (!expected) return fail(500, 'server_misconfigured', 'WEBHOOK_API_KEY is not set on the server');
const provided = req.headers['x-api-key'];
if (!provided || provided !== expected) return fail(401, 'unauthorized', 'Missing or invalid x-api-key header');

// --- 2. codice_cliente -------------------------------------------------
const customerCode = (req.body?.codice_cliente ?? '').toString().trim().toUpperCase();
if (!/^CL-\d{5}$/.test(customerCode)) return fail(400, 'bad_request', 'codice_cliente is required and must match CL-00000');

// --- 3. descrizione ------------------------------------------------------
const description = (req.body?.descrizione ?? '').toString().trim();
if (description.length < 10 || description.length > 1000) return fail(400, 'bad_request', 'descrizione must be between 10 and 1000 characters');

// --- 4. priorita (optional, Italian or English, default medium) ---------
const PRIORITIES = { bassa: 'low', low: 'low', media: 'medium', medium: 'medium', alta: 'high', high: 'high' };
const rawPriority = (req.body?.priorita ?? '').toString().trim().toLowerCase();
// Unknown or missing value falls back to medium: an explicit NULL would NOT
// trigger the column DEFAULT and would violate NOT NULL.
const priority = PRIORITIES[rawPriority] ?? 'medium';

// --- 5. conversation_id (idempotency key: one ticket per conversation) ---
const conversationId = (req.body?.conversation_id ?? '').toString().trim();
if (!conversationId) return fail(400, 'bad_request', 'conversation_id is required');

return [{
  json: {
    valid: true,
    customer_code: customerCode,
    description,
    priority,
    request_id: conversationId,
  },
}];

